window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[8]={"id":"008","numero":8,"titre":"Discriminations","objectifs":[{"id":"8-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition et les mécanismes des discriminations","contenu":"<div class=\"callout callout-info\"><strong>Définition.</strong> La <span class=\"kw-def\">discrimination</span> est un <span class=\"kw-def\">traitement différentiel et défavorable</span> envers une personne ou un groupe de personnes : c'est un acte <span class=\"kw-alerte\">illégal et sanctionné</span>.</div>\n      <p>Le caractère discriminatoire suppose la réunion de <strong>deux conditions</strong> :</p>\n      <ul>\n        <li>être fondé sur un <strong><span class=\"kw-def\">critère</span></strong> défini comme discriminatoire par la loi (<span class=\"kw-etio\">origine</span>, <span class=\"kw-etio\">âge</span>, <span class=\"kw-etio\">handicap</span>, <span class=\"kw-etio\">sexe</span>, <span class=\"kw-etio\">religion</span>, <span class=\"kw-etio\">apparence physique</span>…) ;</li>\n        <li>s'exercer dans un <strong><span class=\"kw-def\">domaine prévu par la loi</span></strong> (éducation, accès à un emploi, à un logement, à un service public ou privé…).</li>\n      </ul>\n\n      <h4>Discrimination directe vs indirecte</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Directe</span></strong> : <span class=\"kw-clinique\">délibérée</span>, visible, affichée voire revendiquée.</li>\n        <li><strong><span class=\"kw-def\">Indirecte</span></strong> : <span class=\"kw-clinique\">systémique</span> ; pratique apparemment neutre susceptible d'entraîner un <span class=\"kw-alerte\">désavantage particulier</span> pour certaines personnes — sauf si elle est justifiée objectivement par un but légitime.</li>\n      </ul>\n\n      <h4>Cadre juridique : une lutte garantie à trois niveaux</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Droit français</span></strong> ;</li>\n        <li><strong><span class=\"kw-def\">Droit communautaire</span></strong> (traité sur le fonctionnement de l'Union européenne) ;</li>\n        <li><strong><span class=\"kw-def\">Droit international</span></strong> (Déclaration universelle des droits de l'Homme des Nations unies, conventions de l'<span class=\"kw-def\">OIT</span> et du Conseil de l'Europe).</li>\n      </ul>\n\n      <h4>Critères de discrimination (25 reconnus par la loi)</h4>\n      <p>On dénombre <strong><span class=\"kw-chiffre\">25 critères</span></strong> ; le <strong><span class=\"kw-chiffre\">25ᵉ</span> et dernier en date</strong>, créé en <span class=\"kw-chiffre\">2016</span>, est l'<strong><span class=\"kw-def\">identité de genre</span></strong>. Exemples :</p>\n      <ul>\n        <li><span class=\"kw-etio\">apparence physique</span>, <span class=\"kw-etio\">âge</span>, <span class=\"kw-etio\">état de santé</span>, <span class=\"kw-etio\">handicap</span>, <span class=\"kw-etio\">grossesse</span> ;</li>\n        <li><span class=\"kw-etio\">sexe</span>, <span class=\"kw-etio\">identité de genre</span>, <span class=\"kw-etio\">orientation sexuelle</span>, <span class=\"kw-etio\">mœurs</span>, <span class=\"kw-etio\">situation de famille</span> ;</li>\n        <li>appartenance vraie ou supposée à une prétendue <span class=\"kw-etio\">« race »</span>, une <span class=\"kw-etio\">nation</span> ou une <span class=\"kw-etio\">ethnie</span>, <span class=\"kw-etio\">origine géographique</span>, <span class=\"kw-etio\">religion</span> ;</li>\n        <li><span class=\"kw-etio\">opinions politiques</span> ou <span class=\"kw-etio\">philosophiques</span>, <span class=\"kw-etio\">activités syndicales</span>, <span class=\"kw-etio\">caractéristiques génétiques</span> ;</li>\n        <li><span class=\"kw-etio\">nom de famille</span>, <span class=\"kw-etio\">lieu de résidence</span>, <span class=\"kw-etio\">domiciliation bancaire</span>, <span class=\"kw-etio\">perte d'autonomie</span>, <span class=\"kw-etio\">vulnérabilité économique</span>, capacité à s'exprimer dans une langue étrangère.</li>\n      </ul>\n\n      <h4>Domaines prévus par la loi</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Emploi</span></strong>, stage, apprentissage, travail indépendant ;</li>\n        <li><strong><span class=\"kw-def\">Éducation</span></strong> ;</li>\n        <li><strong><span class=\"kw-def\">Protection sociale</span></strong>, santé, avantages sociaux ;</li>\n        <li><strong><span class=\"kw-def\">Logement</span></strong>, service public ;</li>\n        <li>accès et <strong><span class=\"kw-def\">fourniture de biens et de services</span></strong>.</li>\n      </ul>\n\n      <h4>Principales dates</h4>\n      <table>\n        <thead><tr><th>Année</th><th>Apport législatif</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-chiffre\">2005</span></td><td>Loi pour l'égalité des droits et des chances des personnes handicapées : <span class=\"kw-def\">obligation d'accessibilité des ERP</span>, création des <span class=\"kw-def\">MDPH</span> (guichet unique) et droit à compensation, éducation en milieu ordinaire.</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2008</span></td><td>Introduction explicite des notions de discrimination <span class=\"kw-def\">directe</span> et <span class=\"kw-def\">indirecte</span> ; réforme constitutionnelle à l'origine de la création du <span class=\"kw-def\">Défenseur des droits</span>.</td></tr>\n          <tr><td><span class=\"kw-chiffre\">2016</span></td><td>Loi de modernisation de la justice du XXIᵉ siècle : création du dernier critère, l'<span class=\"kw-def\">identité de genre</span>, et possibilité d'une <span class=\"kw-def\">action de groupe</span> en justice.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Mécanismes : de la catégorisation à la discrimination</h4>\n      <p>La discrimination est le <span class=\"kw-def\">résultat évitable d'un processus social</span> dont la première étape est la <strong><span class=\"kw-def\">catégorisation</span></strong> : un mécanisme social intériorisé et actionné par tous, qui consiste à découper le monde social selon des traits caractéristiques afin d'identifier les groupes et de se positionner dans la société.</p>\n      <div class=\"callout callout-warn\"><strong>Attention.</strong> La <strong>catégorisation n'est pas une discrimination</strong> et n'entraîne pas systématiquement de situation discriminatoire ; de même, <strong>émettre un préjugé</strong> n'entraîne pas automatiquement un comportement discriminatoire : ce n'est qu'une <span class=\"kw-def\">étape</span> du processus.</div>\n\n      <h4>Préjugé, stéréotype, stigmatisation</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Préjugé</span></strong> : jugement de valeur ou idée préconçue à l'encontre d'un groupe, lui attribuant des caractéristiques non fondées sur la réalité ; <span class=\"kw-clinique\">antérieur à l'expérience</span> et à la connaissance, il prédispose à agir défavorablement.</li>\n        <li><strong><span class=\"kw-def\">Stéréotype</span></strong> : image préconçue, représentation simplifiée d'un individu ou d'un groupe reposant sur une croyance partagée (attributs physiques, moraux, comportementaux) ; attitudes <span class=\"kw-clinique\">simplifiées à l'extrême</span>, souvent erronées.</li>\n        <li><strong><span class=\"kw-def\">Stigmatisation</span></strong> : processus dynamique de <span class=\"kw-clinique\">dévaluation</span> discréditant significativement un individu aux yeux des autres ; le <strong><span class=\"kw-def\">stigmate</span></strong> (attribut discriminant) est corporel (couleur de peau, morphologie), lié à la personnalité ou à l'histoire (<span class=\"kw-clinique\">santé mentale</span>, détention, sexualité), <span class=\"kw-clinique\">visible ou non</span>.</li>\n      </ul>\n\n      <h4>Cycle de la discrimination (4 étapes)</h4>\n      <ol>\n        <li><strong><span class=\"kw-def\">Étiqueter</span></strong> : distinguer selon certaines différences visibles ;</li>\n        <li><strong><span class=\"kw-def\">Stéréotyper</span></strong> : généraliser des défauts à partir d'une caractéristique ;</li>\n        <li><strong><span class=\"kw-def\">Séparer</span></strong> : différencier certaines personnes des autres ;</li>\n        <li><strong><span class=\"kw-def\">Discriminer</span></strong> : priver une personne d'égalité, la traiter différemment aux yeux de la loi.</li>\n      </ol>\n      <p>La graduation complète, ou <strong><span class=\"kw-def\">cycle des discriminations</span></strong>, va de la <span class=\"kw-def\">catégorisation</span> aux <span class=\"kw-def\">stéréotypes et préjugés</span>, puis à la <span class=\"kw-def\">stigmatisation</span>, jusqu'aux <span class=\"kw-def\">actes et comportements discriminatoires</span> — aboutissant au <span class=\"kw-alerte\">racisme</span>, au <span class=\"kw-alerte\">sexisme</span>, à la <span class=\"kw-alerte\">xénophobie</span> et à l'<span class=\"kw-alerte\">homophobie</span>.</p>\n      <p class=\"obj-source\"><em>Distillé depuis le Collège de Médecine légale et Santé publique (item 8).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 7 — Droits individuels et collectifs du patient · 9 — Éthique et déontologie médicale</em></p>","frequence":0},{"id":"8-2","rang":"B","rubrique":"Définition","titre":"Connaître les principaux effets des discriminations sur les inégalités sociales et inégalités de santé","contenu":"<div class=\"callout callout-info\"><strong>Principe.</strong> Les discriminations contreviennent au <span class=\"kw-def\">principe fondamental de l'égalité des droits</span> entre les citoyens. En pratique elles sont <span class=\"kw-clinique\">plus rares</span> que les <span class=\"kw-def\">inégalités sociales</span>, mais <span class=\"kw-alerte\">d'autant plus violentes</span> car elles touchent l'<span class=\"kw-clinique\">identité même</span> des individus : couleur de peau, genre, origine, âge, handicap, orientation sexuelle.</div>\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Toute <strong>inégalité n'est pas illégale</strong> et ne constitue pas forcément une discrimination — mais <strong>toute discrimination est une inégalité</strong>.</div>\n\n      <p>La lutte contre les <strong><span class=\"kw-def\">inégalités sociales et territoriales de santé</span></strong> (ISS) est un véritable <span class=\"kw-def\">enjeu de santé publique</span> : nombreuses et importantes, ces inégalités sont <span class=\"kw-etio\">préexistantes</span> et ont été <span class=\"kw-etio\">amplifiées</span> par la crise et les mesures sanitaires de la pandémie de <strong><span class=\"kw-def\">COVID-19</span></strong>.</p>\n\n      <h4>Populations vulnérabilisées (exemple de la pandémie de COVID-19)</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Catégories sociales les plus pauvres</span></strong> : dégradation des conditions de travail (<span class=\"kw-clinique\">femmes ++</span>) et situation économique détériorée ;</li>\n        <li>personnes concernées par le <strong><span class=\"kw-bio\">VIH</span></strong> et les <strong><span class=\"kw-bio\">hépatites</span></strong> : complications médicales liées aux <span class=\"kw-etio\">comorbidités</span>, <span class=\"kw-etio\">précarisation économique</span>, obstacles d'accès aux services de santé et <span class=\"kw-clinique\">stigmatisation</span> ;</li>\n        <li>personnes <strong><span class=\"kw-def\">LGBT+</span></strong> (lesbiennes, gaies, bi, trans et minorités de genre) : durement impactées par le confinement, plus exposées aux <span class=\"kw-alerte\">violences</span> au sein de la cellule familiale.</li>\n      </ul>\n\n      <h4>Impact des discriminations sur l'état de santé</h4>\n      <p>Les <strong><span class=\"kw-def\">populations vulnérables</span></strong> discriminées sont exposées à davantage de risques et susceptibles d'être désavantagées du point de vue de leur état de santé ou de leur accès aux soins :</p>\n      <ul>\n        <li><strong><span class=\"kw-def\">Minorités sexuelles</span></strong> (personnes lesbiennes, gaies, bisexuelles) : impacts sur la <span class=\"kw-clinique\">santé mentale</span>, risque de <span class=\"kw-alerte\">violences</span>, accentuation du <span class=\"kw-clinique\">stress</span> avec symptômes <span class=\"kw-clinique\">dépressifs</span>, <span class=\"kw-clinique\">anxieux</span> et <span class=\"kw-clinique\">psychotiques</span>, et <strong><span class=\"kw-alerte\">facteur de risque suicidaire</span></strong> ;</li>\n        <li>personnes en <strong><span class=\"kw-def\">surpoids</span></strong> ou en situation d'<strong><span class=\"kw-def\">obésité</span></strong> : <span class=\"kw-clinique\">qualité de vie</span> engagée, <span class=\"kw-clinique\">auto-stigmatisation</span>, prise de poids et <span class=\"kw-clinique\">état de stress</span> élevé.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\"><strong>Cercle vicieux.</strong> Subir une discrimination peut <strong>en retour aggraver l'état de santé</strong> des personnes discriminées : un <span class=\"kw-alerte\">cercle vicieux</span> qui creuse encore les inégalités sociales de santé.</div>\n      <p class=\"obj-source\"><em>Distillé depuis le Collège de Médecine légale et Santé publique (item 8).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 2 — Valeurs professionnelles du médecin · 20 — Inégalités sociales et territoriales de santé</em></p>","frequence":0},{"id":"8-3","rang":"B","rubrique":"Définition","titre":"Connaître les discriminations et leurs formes dans le système de santé","contenu":"<div class=\"callout callout-info\"><strong>Triple problématique.</strong> Le rapport entre <span class=\"kw-def\">discriminations et santé</span> s'articule autour de trois axes :\n        <ul>\n          <li>l'<strong><span class=\"kw-def\">état de santé</span></strong> peut être à l'origine d'un comportement discriminatoire (critère fixé par la loi) ;</li>\n          <li>le <strong><span class=\"kw-def\">système de santé</span></strong> peut lui-même produire des discriminations, souvent <span class=\"kw-def\">indirectes</span> (accès aux soins, refus de soins) ;</li>\n          <li>subir une discrimination peut entraîner des <span class=\"kw-alerte\">conséquences sur l'état de santé</span> des personnes discriminées.</li>\n        </ul>\n      </div>\n\n      <h4>1. L'état de santé à l'origine de situations de discrimination</h4>\n      <table>\n        <thead><tr><th>Situation</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Handicap</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Ampleur :</strong> principal motif déclaré de discrimination, <span class=\"kw-chiffre\">21 %</span> des saisines du Défenseur des droits ;</li>\n                <li><strong>Emploi :</strong> accès difficile au travail ; taux de chômage <span class=\"kw-chiffre\">×2</span> ; inégalités de traitement (femmes ++) ;</li>\n                <li><strong>Éducation :</strong> accès difficile à la scolarisation en milieu ordinaire ; moqueries subies par les enfants ;</li>\n                <li><strong>Soins :</strong> besoins importants ; difficultés financières et environnement inadapté ; communication dégradée avec les soignants.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Obésité</span></strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-def\">Grossophobie</span> :</strong> attitudes stigmatisantes et préjugés envers les personnes en surpoids ou obèses ;</li>\n                <li><strong>Caractère :</strong> discrimination ancienne mais récurrente, fréquente et persistante ;</li>\n                <li><strong>Domaines :</strong> emploi, lieu de travail, école, lieux publics ; <span class=\"kw-clinique\">santé</span> (médecin refusant de soigner, matériel inadapté).</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-bio\">VIH</span> / hépatites</strong></td>\n            <td>\n              <ul>\n                <li><strong>Populations cibles :</strong> les plus précaires et éloignées du système de santé (HSH, femmes nées à l'étranger, personnes trans, travailleurs du sexe) ;</li>\n                <li><strong>Conséquence :</strong> majoration de la <span class=\"kw-etio\">précarisation</span> ; obstacles au démarrage et à la poursuite du <span class=\"kw-def\">suivi</span> médical.</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Santé mentale</span></strong></td>\n            <td>\n              <ul>\n                <li><strong>Personnes suivies en psychiatrie (et entourage) :</strong> image sociale défavorable, rejet (éducation, logement, emploi, justice, santé) ;</li>\n                <li><strong>Conséquence :</strong> dissimulation des situations vécues, <span class=\"kw-alerte\">retard d'accès aux soins</span> ; crainte d'être discriminé en consultant.</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>2. Le système de santé à l'origine de discriminations</h4>\n      <p><strong>Accès aux soins et à la prévention</strong> — facteurs limitants :</p>\n      <ul>\n        <li><span class=\"kw-etio\">conditions économiques</span> : coût de certains soins ;</li>\n        <li><span class=\"kw-etio\">conditions de vie et de travail</span> : horaires décalés, difficulté à consulter aux heures ouvrables ;</li>\n        <li>comportements différenciés selon l'<span class=\"kw-etio\">identité de genre</span>.</li>\n      </ul>\n\n      <h4>Refus d'actes de soins : licite vs illicite</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Refus licite / légitime</span></strong> : professionnel non compétent, sans préjudice pour la personne.</li>\n        <li><strong><span class=\"kw-alerte\">Refus illicite</span></strong> : dispensation de soins non consciencieux, <span class=\"kw-alerte\">abstention d'agir en cas d'urgence</span>, <span class=\"kw-alerte\">défaillance</span> de la permanence ou de la continuité des soins, refus de vente (pharmaciens, dispositifs médicaux), refus de soins aux <span class=\"kw-etio\">détenus</span>, comportement conduisant à un <span class=\"kw-alerte\">renoncement aux soins</span>.</li>\n      </ul>\n\n      <h4>Situations à risque de discrimination dans le soin</h4>\n      <ul>\n        <li><strong><span class=\"kw-etio\">Origine ethnoraciale</span></strong> : discriminations directes, accès aux soins difficile pour les personnes d'origine étrangère ou présumée, orientation vers une offre dérogatoire au droit commun ;</li>\n        <li><strong><span class=\"kw-def\">Organisation du système de soins</span></strong> : discriminations indirectes (budgétaires, d'accueil) ; à l'inverse, l'élargissement des horaires et les dispositifs médicosociaux réduisent ces inégalités d'accès ;</li>\n        <li><strong><span class=\"kw-etio\">Origine économique, géographique</span></strong> : refus de soins aux bénéficiaires de la <strong><span class=\"kw-def\">CMU-c</span></strong>, de la <strong><span class=\"kw-def\">CSS</span></strong> ou de l'<strong><span class=\"kw-def\">AME</span></strong> ;</li>\n        <li><strong>Statut sérologique vis-à-vis du <span class=\"kw-bio\">VIH</span></strong> : refus direct ou indirect de soins invasifs ou gynécologiques (y compris post-mortem).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Prises en charge soignante et préventive.</strong> Des traitements différentiels selon le <span class=\"kw-etio\">niveau d'éducation</span>, les <span class=\"kw-etio\">ressources économiques</span> ou le <span class=\"kw-etio\">genre</span> créent des inégalités de prise en charge — <span class=\"kw-alerte\">difficiles à repérer</span>, le comportement du professionnel étant parfois le produit d'un système discriminatoire plus que d'une intention individuelle.</div>\n\n      <h4>Lutter contre les discriminations dans le soin</h4>\n      <p>Aucune personne ne peut faire l'objet de discriminations dans l'accès à la prévention et aux soins (<strong><span class=\"kw-def\">Code de la santé publique</span></strong>). Le <strong><span class=\"kw-def\">Code de déontologie médicale</span></strong> impose au médecin de soigner «&nbsp;avec la même conscience toutes les personnes&nbsp;» quels que soient leur origine, leurs mœurs, leur situation de famille, leur appartenance, leur handicap ou leur état de santé.</p>\n      <p><strong>Auteurs présumés :</strong> personnes <span class=\"kw-def\">physiques</span> (individus), <span class=\"kw-def\">morales</span> (associations, sociétés), <span class=\"kw-def\">privées</span> (entreprises) et <span class=\"kw-def\">publiques</span> (État, collectivités territoriales, services publics hospitaliers).</p>\n\n      <h4>Voies de recours de la victime</h4>\n      <ul>\n        <li>saisine du <strong><span class=\"kw-def\">Défenseur des droits</span></strong> (la victime pouvant être représentée), voire auto-saisine ;</li>\n        <li>recours aux parlementaires français ou européens et aux institutions étrangères ;</li>\n        <li>site internet dédié (formulaire, ligne téléphonique, messagerie instantanée) ;</li>\n        <li>dans le champ de la santé : directeur de l'<span class=\"kw-def\">organisme local d'Assurance maladie</span>, ordre professionnel concerné, établissement de santé avec <strong><span class=\"kw-def\">médiateur de la CDU</span></strong> (commission des usagers).</li>\n      </ul>\n      <p class=\"obj-source\"><em>Distillé depuis le Collège de Médecine légale et Santé publique (item 8) et les fiches sources (refus de soins, Défenseur des droits).</em></p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 7 — Droits individuels et collectifs du patient · 57 — Handicap · 253 — Obésité</em></p>","frequence":0}],"astuces":[],"strategie":{},"cards":[{"i":"615f3a568efb","n":8,"o":"8-1","u":"Définition","t":"Connaître la définition et les mécanismes des discriminations","q":"Quelle est la différence entre discrimination directe et discrimination indirecte ?","a":"<ul><li>La discrimination <strong>directe</strong> est <strong>délibérée, visible, affichée</strong>, voire revendiquée.</li><li>La discrimination <strong>indirecte</strong> est <strong>systémique</strong> ; il s'agit d'une pratique apparemment neutre, mais susceptible d'entraîner un désavantage particulier pour certaines personnes, sauf si elle est objectivement justifiée par un but légitime.</li></ul>"},{"i":"663a2749aa09","n":8,"o":"8-1","u":"Définition","t":"Connaître la définition et les mécanismes des discriminations","q":"Citez au moins cinq des 25 critères de discrimination reconnus par la loi française.","a":"<p>Parmi les 25 critères reconnus, on peut citer : l'<strong>origine</strong>, l'<strong>âge</strong>, le <strong>handicap</strong>, le <strong>sexe</strong>, l'<strong>identité de genre</strong>, l'<strong>orientation sexuelle</strong>, l'<strong>état de santé</strong>, la <strong>grossesse</strong>, l'<strong>appartenance ethnique</strong>, la <strong>religion</strong>, ou encore les <strong>opinions politiques</strong>.</p>"},{"i":"7b5e28e2c825","n":8,"o":"8-1","u":"Définition","t":"Connaître la définition et les mécanismes des discriminations","q":"Quelles sont les deux conditions nécessaires pour caractériser un acte comme discriminatoire ?","a":"<ul><li>Le traitement doit être fondé sur un <strong>critère</strong> défini comme discriminatoire par la loi (ex: origine, âge, handicap, sexe, religion, apparence physique).</li><li>Il doit s'exercer dans un <strong>domaine</strong> prévu par la loi (ex: éducation, accès à un emploi, à un logement, à un service public ou privé).</li></ul>"},{"i":"9bd354f936d2","n":8,"o":"8-1","u":"Définition","t":"Connaître la définition et les mécanismes des discriminations","q":"Quelle est la définition légale d'une discrimination ?","a":"<p>La discrimination se définit comme un traitement <strong>différentiel et défavorable</strong> envers une personne ou un groupe de personnes. C'est un acte <strong>illégal et sanctionné</strong> par la loi.</p>"},{"i":"ea70b1e26774","n":8,"o":"8-1","u":"Définition","t":"Connaître la définition et les mécanismes des discriminations","q":"Quels sont les principaux domaines dans lesquels la discrimination est prohibée par la loi ?","a":"<ul><li>L'<strong>emploi</strong>, le stage, l'apprentissage, le travail indépendant.</li><li>L'<strong>éducation</strong>.</li><li>La <strong>protection sociale</strong>, la santé, les avantages sociaux.</li><li>Le <strong>logement</strong>, les services publics.</li><li>L'<strong>accès et la fourniture de biens et de services</strong>.</li></ul>"},{"i":"f0b1c3bcdf33","n":8,"o":"8-1","u":"Définition","t":"Connaître la définition et les mécanismes des discriminations","q":"Décrivez les étapes du cycle menant à la discrimination.","a":"<p>Le cycle de la discrimination se décompose en quatre étapes principales :</p><ul><li><strong>Étiqueter</strong> : distinguer selon certaines différences visibles.</li><li><strong>Stéréotyper</strong> : généraliser des défauts à partir d'une caractéristique.</li><li><strong>Séparer</strong> : différencier certaines personnes des autres.</li><li><strong>Discriminer</strong> : priver une personne d'égalité, la traiter différemment aux yeux de la loi.</li></ul>"}]};